<?php if(!defined('SW_APP')||!SW_PUBLIC){http_response_code(404);exit;}$rows=all("SELECT r.id,r.title,a.winning_number,a.prize_type,a.amount_cents,a.status FROM prize_awards a JOIN participants p ON p.id=a.participant_id AND p.raffle_id=a.raffle_id JOIN raffles r ON r.id=a.raffle_id WHERE p.user_id=? UNION ALL SELECT r.id,r.title,w.winning_number,r.type,NULL,w.claim_status FROM winners w JOIN participants p ON p.id=w.participant_id AND p.raffle_id=w.raffle_id JOIN raffles r ON r.id=w.raffle_id WHERE r.draw_version=0 AND p.user_id=?",[$u['id'],$u['id']]);?>
<p class="user-sub">Premios asociados a tus participaciones. La entrega no es automática.</p><?php if(!$rows):?><div class="user-empty">No hay premios registrados a tu nombre.</div><?php else:?><div class="user-table"><table><thead><tr><th>Sorteo</th><th>Número</th><th>Premio</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h(str_pad((string)$r['winning_number'],4,'0',STR_PAD_LEFT))?></td><td><?=$r['prize_type']==='producto'?'Producto':($r['amount_cents']===null?'Dinero':money($r['amount_cents']))?></td><td><?=h($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
